(function() {
  var _result = {};
  try {
    var comp = app.project.activeItem;
    if (!comp || !(comp instanceof CompItem)) {
      _result = {status:"error", message:"No active comp"};
      return JSON.stringify(_result);
    }
    var p = {
      layerName: ${layerName},
      startColor: ${startColor},
      endColor: ${endColor},
      startPoint: ${startPoint},
      endPoint: ${endPoint},
      scatter: ${scatter}
    };
    var layer = comp.layers.byName(p.layerName);
    if (!layer) {
      layer = comp.layers.addSolid([0.5,0.5,0.5], p.layerName, comp.width, comp.height, comp.pixelAspect, comp.duration);
    }
    var ramp = layer.Effects.addProperty("ADBE Ramp");
    ramp.property("ADBE Ramp-0002").setValue(p.startColor);
    ramp.property("ADBE Ramp-0004").setValue(p.endColor);
    ramp.property("ADBE Ramp-0001").setValue(p.startPoint);
    ramp.property("ADBE Ramp-0003").setValue(p.endPoint);
    ramp.property("ADBE Ramp-0005").setValue(1);
    ramp.property("ADBE Ramp-0006").setValue(p.scatter);
    _result = {status:"success", message:"线性渐变背景已应用"};
  } catch(e) {
    _result = {status:"error", message:"Error: " + e.toString()};
  }
  return JSON.stringify(_result);
})();

